import React from 'react'

export default function Pizza({pizza}) {
    return(
        <div>
           <h1>{pizza.name}</h1>
           <img src={pizza.image} alt=''/>
           <div className='flex-container'>
            <div className='w-100'>
            <p>taille</p>
               <select>
                {pizza.varients.map(varient=>{
                    return
                    <option value={varient}>{varient}</option>
                })}
            
              </select></div>
               <div className='w-100'>
               <p>quantite</p>
                <input type='number'/>
                </div>

                </div>
        </div>
    )
    
}
